package com.mlserving.inference

import java.nio.{ByteBuffer, ByteOrder}
import java.util.concurrent.{ConcurrentHashMap, Executors}
import scala.collection.mutable
import scala.concurrent.{ExecutionContext, Future}

// Native library interface for optimized tensor operations
object NativeTensorOps {
  System.loadLibrary("tensor_ops")

  @native def allocateTensorBuffer(sizeBytes: Long): Long  // returns native pointer
  @native def freeTensorBuffer(ptr: Long): Unit
  @native def copyToNative(src: Array[Float], destPtr: Long, offsetBytes: Long, lengthBytes: Long): Int
  @native def runInference(modelPtr: Long, inputPtr: Long, outputPtr: Long, batchSize: Int): Int
  @native def loadModel(path: String): Long
  @native def getModelInputSize(modelPtr: Long): Long
  @native def getModelOutputSize(modelPtr: Long): Long
}

// Manages lifecycle of native tensor memory with reference counting
class NativeTensorPool(maxPoolSize: Int = 64) {
  private val pool = new ConcurrentHashMap[Long, TensorAllocation]()
  private val freeList = new java.util.concurrent.ConcurrentLinkedQueue[Long]()

  case class TensorAllocation(ptr: Long, sizeBytes: Long, refCount: java.util.concurrent.atomic.AtomicInteger)

  def acquire(sizeBytes: Long): Long = {
    val cached = freeList.poll()
    if (cached != 0L && cached != null.asInstanceOf[Long]) {
      val alloc = pool.get(cached)
      if (alloc != null && alloc.sizeBytes >= sizeBytes) {
        alloc.refCount.incrementAndGet()
        return alloc.ptr
      } else {
        // Size mismatch, free and allocate new
        if (alloc != null) NativeTensorOps.freeTensorBuffer(alloc.ptr)
        pool.remove(cached)
      }
    }
    val ptr = NativeTensorOps.allocateTensorBuffer(sizeBytes)
    val alloc = TensorAllocation(ptr, sizeBytes, new java.util.concurrent.atomic.AtomicInteger(1))
    pool.put(ptr, alloc)
    ptr
  }

  def release(ptr: Long): Unit = {
    val alloc = pool.get(ptr)
    if (alloc != null) {
      val remaining = alloc.refCount.decrementAndGet()
      if (remaining <= 0) {
        if (pool.size() < maxPoolSize) {
          freeList.offer(ptr)
        } else {
          pool.remove(ptr)
          NativeTensorOps.freeTensorBuffer(ptr)
        }
      }
    }
  }
}

// Request batching for inference optimization
class InferenceBatcher(modelPtr: Long, tensorPool: NativeTensorPool) {
  private val inputSize = NativeTensorOps.getModelInputSize(modelPtr)
  private val outputSize = NativeTensorOps.getModelOutputSize(modelPtr)

  implicit val ec: ExecutionContext = ExecutionContext.fromExecutor(
    Executors.newFixedThreadPool(Runtime.getRuntime.availableProcessors())
  )

  // Computes required buffer size for a batch
  // Uses 32-bit float (4 bytes per element)
  private def computeBufferSize(batchSize: Int, tensorElements: Long): Long = {
    // Critical: this multiplication can overflow for large batches with large models
    val elementsTotal = batchSize.toLong * tensorElements
    val bytesNeeded = elementsTotal * 4L  // 4 bytes per float32
    bytesNeeded
  }

  def runBatchInference(inputs: Array[Array[Float]]): Future[Array[Array[Float]]] = Future {
    val batchSize = inputs.length

    // Validate individual input sizes
    inputs.foreach { input =>
      require(input.length.toLong == inputSize, s"Input size mismatch: ${input.length} vs $inputSize")
    }

    // Allocate native buffers for batch
    val inputBufferSize = computeBufferSize(batchSize, inputSize)
    val outputBufferSize = computeBufferSize(batchSize, outputSize)

    val inputPtr = tensorPool.acquire(inputBufferSize)
    val outputPtr = tensorPool.acquire(outputBufferSize)

    try {
      // Copy input data to native memory
      var offset = 0L
      inputs.foreach { input =>
        val copyLen = input.length.toLong * 4L
        NativeTensorOps.copyToNative(input, inputPtr, offset, copyLen)
        offset += copyLen
      }

      // Run inference
      val status = NativeTensorOps.runInference(modelPtr, inputPtr, outputPtr, batchSize)
      require(status == 0, s"Inference failed with status $status")

      // Extract results (simplified - in practice would use JNI to copy back)
      Array.fill(batchSize)(new Array[Float](outputSize.toInt))
    } finally {
      tensorPool.release(inputPtr)
      tensorPool.release(outputPtr)
    }
  }
}

// gRPC-style request handler for Kubernetes inference service
class InferenceServer(modelPath: String) {
  private val modelPtr = NativeTensorOps.loadModel(modelPath)
  private val tensorPool = new NativeTensorPool(maxPoolSize = 128)
  private val batcher = new InferenceBatcher(modelPtr, tensorPool)

  // Handles incoming prediction requests
  // maxBatchSize is configured via K8s ConfigMap, typically 32-256
  def handlePrediction(requestData: Array[Byte], maxBatchSize: Int): Future[Array[Byte]] = {
    implicit val ec: ExecutionContext = ExecutionContext.global

    // Parse protobuf-like request (simplified)
    val floatBuffer = ByteBuffer.wrap(requestData).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer()
    val inputSize = NativeTensorOps.getModelInputSize(modelPtr).toInt

    // Determine batch size from request payload
    val totalFloats = requestData.length / 4
    val batchSize = totalFloats / inputSize

    // Security check: limit batch size
    val effectiveBatchSize = math.min(batchSize, maxBatchSize)

    // Reconstruct input arrays
    val inputs = (0 until effectiveBatchSize).map { i =>
      val arr = new Array[Float](inputSize)
      floatBuffer.position(i * inputSize)
      floatBuffer.get(arr)
      arr
    }.toArray

    batcher.runBatchInference(inputs).map { results =>
      // Serialize results back
      val outBuf = ByteBuffer.allocate(results.length * results(0).length * 4)
        .order(ByteOrder.LITTLE_ENDIAN)
      results.foreach(r => outBuf.asFloatBuffer().put(r))
      outBuf.array()
    }
  }
}

// Health check and metrics for K8s liveness/readiness probes
object ServerMetrics {
  @volatile var totalInferences: Long = 0L
  @volatile var nativeMemoryAllocated: Long = 0L

  def healthCheck(): Boolean = {
    nativeMemoryAllocated < Runtime.getRuntime.maxMemory() * 0.8
  }
}
